def solution(df):
    out = df.sort_values(['store', 'date']).copy()
    g = out.groupby('store')['sales']
    out['lag1'] = g.shift(1)
    out['roll3'] = g.transform(lambda s: s.rolling(3, min_periods=1).mean())
